// 全ての組合せを試し，見つかる場合・見つからない場合の両方で正しいものがちょうど1つかを確かめる
const tests = [[[6, 2, 9], 2, true], [[6, 2, 9], 5, false], [[7], 7, true], [[], 1, false]];
const ok = [];
for (const a of [true, false]) {
  for (const b of [true, false]) {
    const contains = (arr, x) => {
      for (let i = 1; i <= arr.length; i++) if (arr[i - 1] === x) return a;
      return b;
    };
    if (tests.every(([arr, x, want]) => contains(arr, x) === want)) ok.push('a: ' + a + ' ／ b: ' + b);
  }
}
return ok.length === 1 ? ok[0] : 'answers=' + ok.length;
